 0,1,'PUBLIC_DIAGNOSTIC',1,'MULTIPART',1048576,15000,'00000000-0000-0000-0000-000000000001',UTC_TIMESTAMP(6),'00000000-0000-0000-0000-000000000001',UTC_TIMESTAMP(6));
INSERT INTO API_LOG
(UUID,ACTOR_TYPE,ACTOR_UUID,CORRELATION_ID,OPERATION_UUID,OPERATION_NAME,ENTITY_TYPE,ENTITY_UUID,ACTION_CODE,RESULT_CODE,CHANGE_DETAILS,CREATED_DATETIME)
SELECT UUID(),'WORKLOAD','00000000-0000-0000-0000-000000000001','migration-0003',
 'fa000000-0000-4000-8000-000000000003','REGISTER_SERVICE_METHOD','SERVICE_METHOD',UUID,'CREATE','SUCCEEDED',
 JSON_OBJECT('service',SERVICE_NAME,'method',METHOD_NAME,'verb',METHOD_REQUEST_TYPE,'host',METHOD_HOST,'path',METHOD_PATH,'developmentOnly',DEVELOPMENT_ONLY),UTC_TIMESTAMP(6)
FROM SERVICE_METHOD
